style.css:
/* Estilo general colorido y moderno */
body {
    font-family: 'Arial', sans-serif; /* Fuente sencilla y moderna */
    background-color: #212121; /* Fondo oscuro con matices profundos */
    color: #ffeb3b; /* Texto amarillo brillante */
    margin: 0; /* Eliminar márgenes predeterminados */
    padding: 0; /* Eliminar espaciado predeterminado */
}

/* Enlaces */
a {
    color: #ff4081; /* Enlaces en un color rosa brillante */
    text-decoration: none; /* Sin subrayado en los enlaces */
}

a:hover {
    color: #00bcd4; /* Cambio a azul brillante en hover */
    text-decoration: underline; /* Subrayado cuando se pasa el ratón por encima */
}

/* Títulos */
h1, h2, h3, h4, h5, h6 {
    color: #ff5722; /* Títulos en color naranja vibrante */
    text-transform: uppercase; /* Hacer los títulos en mayúsculas */
}

/* Botones */
button, input[type="button"], input[type="submit"] {
    background-color: #8bc34a; /* Botones verdes */
    color: #212121; /* Texto oscuro en botones */
    border: 2px solid #ff4081; /* Bordes rosados en botones */
    padding: 10px 20px; /* Espaciado interior de los botones */
    cursor: pointer; /* Cambiar el cursor a mano */
    font-weight: bold; /* Botones con texto en negrita */
}

button:hover, input[type="button"]:hover, input[type="submit"]:hover {
    background-color: #00bcd4; /* Fondo azul al pasar el ratón por encima */
    border-color: #ffeb3b; /* Bordes amarillos en hover */
}

/* Formularios */
input, textarea {
    background-color: #424242; /* Fondo gris oscuro en campos de formulario */
    color: #ffeb3b; /* Texto amarillo brillante */
    border: 2px solid #00bcd4; /* Bordes azules brillantes */
    padding: 10px; /* Espaciado interior */
    width: 100%; /* Los campos de formulario ocupan el 100% del ancho */
}

input:focus, textarea:focus {
    border-color: #ff4081; /* Bordes rosas al enfocar */
    outline: none; /* Eliminar el borde de enfoque predeterminado */
}

/* Estilo para tablas */
table {
    background-color: #333333; /* Fondo oscuro en las tablas */
    border: 1px solid #ffeb3b; /* Bordes amarillos en las tablas */
    width: 100%; /* Las tablas ocupan el 100% del ancho */
}

table th, table td {
    color: #ffffff; /* Texto blanco en las celdas */
    padding: 12px 15px; /* Espaciado dentro de las celdas */
    text-align: center; /* Alinear el texto al centro */
}

/* Estilo para las imágenes */
img {
    border-radius: 10px; /* Bordes redondeados en las imágenes */
    max-width: 100%; /* Asegurar que las imágenes se ajusten al tamaño de la pantalla */
    display: block; /* Eliminar espacio adicional debajo de las imágenes */
    margin: 15px 0; /* Margen superior e inferior para separar las imágenes */
}

/* Mejorar la visibilidad de las barras de desplazamiento */
::-webkit-scrollbar {
    width: 12px; /* Ancho de la barra de desplazamiento */
}

::-webkit-scrollbar-thumb {
    background-color: #00bcd4; /* Pulgar de la barra en azul brillante */
    border-radius: 6px; /* Bordes redondeados */
}

::-webkit-scrollbar-thumb:hover {
    background-color: #ff4081; /* Pulgar azul que cambia a rosa en hover */
}

::-webkit-scrollbar-track {
    background-color: #424242; /* Fondo gris oscuro de la pista de desplazamiento */
}
